CREATE TABLE `batch_lineage` (
  `lineage_id` int(11) NOT NULL AUTO_INCREMENT,
  `parent_batch_id` int(11) NOT NULL COMMENT 'Batch of produced product',
  `child_batch_id` int(11) NOT NULL COMMENT 'Batch of consumed ingredient/sub-product',
  `quantity_consumed` decimal(12,2) NOT NULL COMMENT 'Quantity of child batch consumed',
  `jo_number` varchar(50) DEFAULT NULL COMMENT 'Job order that created this lineage',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`lineage_id`),
  KEY `idx_batch_lineage_parent` (`parent_batch_id`),
  KEY `idx_batch_lineage_child` (`child_batch_id`),
  KEY `idx_batch_lineage_jo` (`jo_number`),
  CONSTRAINT `batch_lineage_ibfk_1` FOREIGN KEY (`parent_batch_id`) REFERENCES `fifo_batches` (`batch_id`) ON UPDATE CASCADE,
  CONSTRAINT `batch_lineage_ibfk_2` FOREIGN KEY (`child_batch_id`) REFERENCES `fifo_batches` (`batch_id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
