DROP TABLE IF EXISTS `dispatch_order_lines`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `dispatch_order_lines` (
  `line_id` int(11) NOT NULL AUTO_INCREMENT,
  `do_id` int(11) NOT NULL,
  `item_id` int(11) NOT NULL,
  `qty_ordered` decimal(24,12) NOT NULL,
  `qty_dispatched` decimal(24,12) NOT NULL DEFAULT 0.000000000000,
  `qty_voided` decimal(24,12) NOT NULL DEFAULT 0.000000000000 COMMENT 'Tracks quantity voided after dispatch for audit trail',
  `unit_of_measure` varchar(50) DEFAULT NULL,
  `cost_per_unit` decimal(10,4) DEFAULT NULL COMMENT 'Snapshot of cost at dispatch time for COGS tracking',
  `sale_price_per_unit` decimal(10,4) DEFAULT NULL COMMENT 'Snapshot of selling price at time of DO creation. Null for internal transfers.',
  `batch_id` int(11) DEFAULT NULL COMMENT 'Primary FIFO/FEFO batch consumed for this line',
  `notes` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`line_id`),
  KEY `batch_id` (`batch_id`),
  KEY `idx_dol_do_id` (`do_id`),
  KEY `idx_dol_item_id` (`item_id`),
  KEY `idx_dol_do_item` (`do_id`,`item_id`),
  CONSTRAINT `dispatch_order_lines_ibfk_1` FOREIGN KEY (`do_id`) REFERENCES `dispatch_orders` (`do_id`) ON DELETE CASCADE,
  CONSTRAINT `dispatch_order_lines_ibfk_2` FOREIGN KEY (`item_id`) REFERENCES `items` (`item_id`),
  CONSTRAINT `dispatch_order_lines_ibfk_3` FOREIGN KEY (`batch_id`) REFERENCES `fifo_batches` (`batch_id`)
