  `notes` text DEFAULT NULL COMMENT 'Notes from PO receipt or JO completion',
  `location_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`batch_id`),
  KEY `idx_item_id` (`item_id`),
  KEY `idx_expiry_date` (`expiry_date`),
  KEY `idx_received_date` (`received_date`),
  KEY `idx_fifo_batches_expiry_date` (`expiry_date`),
  KEY `idx_fifo_batches_location_id` (`location_id`),
  CONSTRAINT `fifo_batches_ibfk_1` FOREIGN KEY (`item_id`) REFERENCES `items` (`item_id`) ON DELETE CASCADE,
  CONSTRAINT `fifo_batches_location_id_foreign_idx` FOREIGN KEY (`location_id`) REFERENCES `tenant_locations` (`location_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
