/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `items` (
  `item_id` int(11) NOT NULL AUTO_INCREMENT,
  `sku_code` varchar(50) DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `category` enum('raw_material','packaging','product','supplies','service') NOT NULL,
  `product_type` enum('work_in_progress','finished_goods') DEFAULT NULL,
  `mode_item_preset` varchar(64) DEFAULT NULL COMMENT 'Corrected workflow-mode item preset key used to preserve mode-native item subtype semantics',
  `product_folder` varchar(100) DEFAULT NULL,
  `folder_id` int(11) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `current_stock` decimal(12,2) DEFAULT 0.00,
  `max_capacity` decimal(12,2) DEFAULT NULL,
  `min_threshold` decimal(12,2) DEFAULT NULL,
  `purchase_allowance` decimal(12,2) DEFAULT NULL,
  `unit_of_measure` varchar(50) DEFAULT NULL,
  `cost_per_unit` decimal(10,4) DEFAULT NULL,
  `default_sale_price` decimal(10,4) DEFAULT NULL COMMENT 'Last-used sale price for this item. Auto-updated on each DO dispatch. Defaults to cost_per_unit on first use.',
  `fifo_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `batch_size` decimal(12,2) DEFAULT NULL,
  `yield_percentage` decimal(5,2) DEFAULT NULL,
  `processing_loss` decimal(5,2) DEFAULT NULL,
  `production_notes` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `packaging_specs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Packaging specifications (height, width, thickness, material, design, contents) for packaging category items' CHECK (json_valid(`packaging_specs`)),
  `status` enum('draft','active','inactive') DEFAULT 'active',
  `wizard_metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Stores wizard progress and data for draft products' CHECK (json_valid(`wizard_metadata`)),
  `deleted_by` int(11) DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `nesting_level` int(11) DEFAULT 0 COMMENT '0=raw ingredient, 1-3=nested product levels',
  `max_child_depth` int(11) DEFAULT 0 COMMENT 'Maximum depth of any sub-component used',
  `is_leaf_node` tinyint(1) DEFAULT 1 COMMENT 'FALSE if this item is used as ingredient in another product',
  `composition_hash` varchar(64) DEFAULT NULL COMMENT 'Hash of composition for quick circular detection',
  `shelf_life_days` int(11) DEFAULT NULL COMMENT 'Shelf life in days for unopened items (required if fifo_enabled)',
  `opened_shelf_life_days` int(11) DEFAULT NULL COMMENT 'Shelf life in days after opening',
  `vat_type` enum('vatable','vat_exempt','zero_rated') NOT NULL DEFAULT 'vatable',
  `active_sku_code` varchar(50) GENERATED ALWAYS AS (case when `deleted_at` is null and `status` not in ('draft','inactive') and `sku_code` is not null and trim(`sku_code`) <> '' then ucase(trim(`sku_code`)) else NULL end) STORED,
  PRIMARY KEY (`item_id`),
  UNIQUE KEY `sku_code` (`sku_code`),
  UNIQUE KEY `uq_items_active_sku_code` (`active_sku_code`),
  KEY `idx_category` (`category`),
  KEY `idx_name` (`name`),
  KEY `idx_current_stock` (`current_stock`),
  KEY `idx_item_status` (`status`),
  KEY `idx_sku_code` (`sku_code`),
  KEY `items_deleted_by_foreign_idx` (`deleted_by`),
  KEY `idx_items_nesting_level` (`nesting_level`),
  KEY `idx_items_folder_id` (`folder_id`),
  KEY `idx_items_status` (`status`),
  KEY `idx_items_mode_item_preset` (`mode_item_preset`),
  KEY `idx_items_deleted_at` (`deleted_at`),
  CONSTRAINT `items_deleted_by_foreign_idx` FOREIGN KEY (`deleted_by`) REFERENCES `users` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `items_folder_id_foreign_idx` FOREIGN KEY (`folder_id`) REFERENCES `item_folders` (`folder_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
