DROP TABLE IF EXISTS `pos_transaction_lines`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pos_transaction_lines` (
  `line_id` int(11) NOT NULL AUTO_INCREMENT,
  `pos_transaction_id` int(11) NOT NULL,
  `item_id` int(11) NOT NULL,
  `quantity` decimal(24,12) NOT NULL,
  `unit_of_measure` varchar(50) DEFAULT NULL,
  `cost_snapshot` decimal(10,4) DEFAULT NULL,
  `sale_price` decimal(10,4) NOT NULL,
  `line_subtotal` decimal(14,4) NOT NULL,
  `vat_type_snapshot` enum('vatable','vat_exempt','zero_rated') NOT NULL DEFAULT 'vatable',
  `vat_rate_snapshot` decimal(5,4) NOT NULL DEFAULT 0.1200,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `sale_price_overridden` tinyint(1) NOT NULL DEFAULT 0,
  `price_override_reason` varchar(255) DEFAULT NULL,
  `fnb_course_snapshot` enum('appetizer','main','dessert','drink','other') DEFAULT NULL,
  `fnb_modifiers_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`fnb_modifiers_snapshot`)),
  `fnb_special_instructions` text DEFAULT NULL,
  `fnb_kitchen_station_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`fnb_kitchen_station_snapshot`)),
  PRIMARY KEY (`line_id`),
  KEY `idx_pos_lines_transaction_id` (`pos_transaction_id`),
  KEY `idx_pos_lines_item_id` (`item_id`),
  CONSTRAINT `pos_transaction_lines_ibfk_1` FOREIGN KEY (`pos_transaction_id`) REFERENCES `pos_transactions` (`pos_transaction_id`) ON DELETE CASCADE,
  CONSTRAINT `pos_transaction_lines_ibfk_2` FOREIGN KEY (`item_id`) REFERENCES `items` (`item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=78 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

